 @Test void dispatchIntentIsSingleUseAndExpiredLeaseNeverRequeues(){var s=session(1);var accepted=store.admit(1,command(s,"dispatch-once","q"));var r=claim(s);var sent=store.markDispatch(1,r.id(),r.fence(),"worker-1");assertNotNull(sent.dispatchedAt());fail(409,()->store.markDispatch(1,r.id(),r.fence(),"worker-1"));clock.value=clock.value.plusSeconds(11);assertEquals(1,store.recoverExpired(10));var recovered=store.get(1,r.id());assertEquals("INTERRUPTED",recovered.status());assertTrue(recovered.executionUncertain());assertEquals("DISPATCH_RESULT_UNCERTAIN",recovered.lastError());assertTrue(store.claim(1,s.id(),"worker-2",Duration.ofSeconds(10)).isEmpty());fail(409,()->finish(r,"COMPLETED","late"));assertEquals(accepted.run().id(),store.admit(1,new Admission(s.id(),s.activeBranchId(),0,"dispatch-once","q",List.of(),"mock-text",command(s,"different-key","q").options())).run().id());}
 @Test void expiredBeforeDispatchAlsoStopsWithoutProviderReplay(){var s=session(1);store.admit(1,command(s,"never-dispatched","q"));var r=claim(s);clock.value=clock.value.plusSeconds(11);store.recoverExpired(10);assertFalse(store.get(1,r.id()).executionUncertain());assertEquals("LEASE_EXPIRED_BEFORE_DISPATCH",store.get(1,r.id()).lastError());fail(409,()->store.markDispatch(1,r.id(),r.fence(),"worker-1"));}
 @Test void checkpointsAndCursorRecoveryAreDurableBoundedAndNeverClaim(){var s=session(1);store.admit(1,command(s,"streaming-key","q"));Run r=claim(s);for(int i=0;i<7;i++)r=store.checkpoint(1,r.id(),r.fence(),"worker-1",r.sequence(),"partial"+i,Map.of("delta","分"));var page=store.events(1,r.id(),0,10);assertTrue(page.snapshotRequired());assertEquals("partial6",page.run().checkpoint());assertEquals(4,jdbc.queryForObject("SELECT count(*) FROM assistant_run_events",Integer.class));long seq=r.sequence();assertTrue(store.events(1,r.id(),seq,10).events().isEmpty());Run finalRun=finish(r,"COMPLETED","saved answer");var terminal=store.events(1,r.id(),seq,10).events().get(0);assertEquals("run.state",terminal.type());assertEquals("COMPLETED",terminal.payload().get("state"));assertTrue(finalRun.terminal());assertEquals("saved answer",base.history(1,s.id(),null,false,100).get(1).body());}
 @Test void cancelImmediatelyFencesLateCompletionAndSavesPartial(){var s=session(1);store.admit(1,command(s,"cancel-one","q"));Run r=claim(s);r=store.checkpoint(1,r.id(),r.fence(),"worker-1",r.sequence(),"partial",Map.of("delta","partial"));Run prior=r;var cancelled=store.cancel(1,r.id());assertEquals("CANCELLED",cancelled.status());assertEquals("partial",base.history(1,s.id(),null,false,100).get(1).body());fail(409,()->finish(prior,"COMPLETED","late"));assertEquals(cancelled.id(),store.cancel(1,r.id()).id());}
 @Test void retryForksFromOriginalUserWithoutDuplicatingItOrOldFailedAnswer(){var s=session(1);store.admit(1,command(s,"first-attempt","question"));var r=claim(s);finish(r,"INTERRUPTED","old partial");long version=base.branches(1,s.id()).get(0).version();fail(400,()->store.retry(1,r.id(),"retry-no-ack",version,false));var retry=store.retry(1,r.id(),"retry-accepted",version,true);assertEquals(2,retry.run().attempt());assertEquals(r.id(),retry.run().retryOf());assertNotEquals(r.branchId(),retry.run().branchId());assertEquals(List.of("question"),store.context(1,retry.run().id(),30).stream().map(AssistantRecords.Message::body).toList());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM assistant_messages WHERE role='USER'",Integer.class));assertEquals(retry.run().id(),store.retry(1,r.id(),"retry-accepted",version,true).run().id());assertEquals(retry.run().id(),store.replayRetry(1,r.id(),"retry-accepted",version,true).orElseThrow().run().id());assertTrue(store.timeline(1,s.id()).stream().flatMap(t->t.runs().stream()).anyMatch(run->run.id().equals(retry.run().id())));assertFalse(store.timeline(1,s.id()).stream().flatMap(t->t.runs().stream()).anyMatch(run->run.id().equals(r.id())));assertTrue(store.timeline(1,s.id(),null,true).stream().flatMap(t->t.runs().stream()).anyMatch(run->run.id().equals(r.id())));}
 @Test void editedBranchExecutesItsSavedUserAndKeepsOriginalFutureOut(){var s=session(1);var old=completed(s,"edit-source");var b=base.branches(1,s.id()).get(0);var revised=base.reviseMessage(1,s.id(),b.id(),old.inputMessageId(),b.version(),"edit-request","changed");var admission=new Admission(s.id(),revised.id(),revised.version(),"execute-edited","changed",List.of(),"mock-text",Map.of());var r=store.admitEdited(1,admission).run();assertEquals(List.of("changed"),store.context(1,r.id(),32).stream().map(AssistantRecords.Message::body).toList());assertEquals(2,jdbc.queryForObject("SELECT count(*) FROM assistant_messages WHERE role='USER'",Integer.class));assertEquals(r.id(),store.admitEdited(1,admission).run().id());assertEquals(r.id(),store.replayEdited(1,admission).orElseThrow().run().id());fail(409,()->store.replayEdited(1,new Admission(s.id(),revised.id(),revised.version(),"execute-edited","different",List.of(),"mock-text",Map.of())));}
