 @Test void suspendedSummaryAdmissionKeepsExistingResultsAndAllowsExplicitResume(){var s=session(1);completed(s,"manual-summary-base");Runnable reject=()->{throw new AssistantFailure(503,"ASSISTANT_GENERATION_SUSPENDED","operator paused");};fail(503,()->store.summary(1,s.id(),s.activeBranchId(),"paused-summary","mock-text",Map.of(),3,reject));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM assistant_runs WHERE kind='SUMMARY'",Integer.class));Run accepted=store.summary(1,s.id(),s.activeBranchId(),"paused-summary","mock-text",Map.of(),3,()->{});assertEquals(accepted.id(),store.summary(1,s.id(),s.activeBranchId(),"paused-summary","mock-text",Map.of(),3,reject).id());assertEquals(accepted.id(),store.summary(1,s.id(),s.activeBranchId(),"duplicate-summary","mock-text",Map.of(),3,reject).id());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM assistant_runs WHERE kind='SUMMARY'",Integer.class));assertEquals("QUEUED",store.get(1,accepted.id()).status());}
 @Test void manualPauseRestartResumeUsesOneActualLoopbackExecution()throws Exception{
  Path root=Files.createTempDirectory("assistant-pause-fixture");Files.setPosixFilePermissions(root,java.nio.file.attribute.PosixFilePermissions.fromString("rwx------"));Path marker=root.resolve(AssistantGenerationControl.NAME),token=root.resolve("test-token");Files.writeString(token,"synthetic-internal-token-only");Files.setPosixFilePermissions(token,java.nio.file.attribute.PosixFilePermissions.fromString("rw-------"));
  var server=com.sun.net.httpserver.HttpServer.create(new java.net.InetSocketAddress("127.0.0.1",0),0);var posts=new java.util.concurrent.atomic.AtomicInteger();var json=new com.fasterxml.jackson.databind.ObjectMapper();String digest="a".repeat(64);
  server.createContext("/internal/v1/assistant/models",exchange->{byte[] bytes=json.writeValueAsBytes(Map.of("contractVersion",1,"configSha256",digest,"models",List.of(Map.of("id","mock-text","enabled",true,"configured",true,"capabilities",Map.of("images",false)))));exchange.sendResponseHeaders(200,bytes.length);try(var out=exchange.getResponseBody()){out.write(bytes);}});
  server.createContext("/internal/v1/assistant/executions",exchange->{if(exchange.getRequestURI().getPath().endsWith("/cancel")){exchange.sendResponseHeaders(404,-1);exchange.close();return;}posts.incrementAndGet();exchange.getRequestBody().readAllBytes();byte[] bytes="event: delta\ndata: {\"text\":\"synthetic answer\"}\n\nevent: done\ndata: {}\n\n".getBytes(java.nio.charset.StandardCharsets.UTF_8);exchange.getResponseHeaders().set("Content-Type","text/event-stream");exchange.sendResponseHeaders(200,bytes.length);try(var out=exchange.getResponseBody()){out.write(bytes);}});server.start();
  var p=new AssistantExecutionProperties();p.setEnabled(true);p.setAiBaseUrl("http://127.0.0.1:"+server.getAddress().getPort());p.setAllowLoopbackHttp(true);p.setInternalTokenFile(token.toString());p.setExpectedConfigSha256(digest);p.setPollInterval(Duration.ofMillis(50));
  try(var client=new AssistantAiClient(p,json)){
   var control=new AssistantGenerationControl(root);var s=session(1);var command=new AssistantExecutionService.Command(s.activeBranchId(),0,"pause-durable-key","synthetic question",List.of(),"mock-text",Map.of(),List.of());UUID id;
   try(var service=new AssistantExecutionService(store,base,org.mockito.Mockito.mock(AssistantAttachmentService.class),client,null,null,p,json,clock,control::state)){
    id=service.admit(1,s.id(),command).run().id();Files.writeString(marker,AssistantGenerationControl.CONTENT);Files.setPosixFilePermissions(marker,java.nio.file.attribute.PosixFilePermissions.fromString("rw-------"));service.tick();assertEquals(0,posts.get());assertEquals("QUEUED",store.get(1,id).status());assertEquals(id,service.admit(1,s.id(),command).run().id());assertEquals(0,posts.get());
   }
   try(var resumed=new AssistantExecutionService(store,base,org.mockito.Mockito.mock(AssistantAttachmentService.class),client,null,null,p,json,clock,new AssistantGenerationControl(root)::state)){
    resumed.tick();assertEquals(0,posts.get());assertEquals("QUEUED",store.get(1,id).status());Files.delete(marker);resumed.tick();long deadline=System.nanoTime()+TimeUnit.SECONDS.toNanos(5);while(!store.get(1,id).terminal()&&System.nanoTime()<deadline)Thread.sleep(20);assertEquals("COMPLETED",store.get(1,id).status());assertEquals("synthetic answer",store.get(1,id).checkpoint());assertEquals(1,posts.get());resumed.tick();assertEquals(1,posts.get());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM assistant_runs",Integer.class));
   }
  }finally{server.stop(0);try(var paths=Files.walk(root)){for(var path:paths.sorted(Comparator.reverseOrder()).toList())Files.delete(path);}}
 }
 @Test void executingSummaryRemainsExecutingWhenNewChatArrives(){var s=session(1);completed(s,"summary-start");var summary=store.summary(1,s.id(),s.activeBranchId(),"running-summary","mock-text",Map.of());var executing=claim(s);var chat=store.admit(1,command(s,"waiting-chat","new"));assertEquals(summary.id(),executing.id());assertEquals("EXECUTING",store.get(1,executing.id()).status());assertTrue(store.claim(1,s.id(),"other",Duration.ofSeconds(5)).isEmpty());finish(executing,"COMPLETED","summary result");assertEquals(chat.run().id(),claim(s).id());}
 @Test void summaryFailuresRequireExplicitRetryAndKeepSeparateRunAccounting(){var s=session(1);completed(s,"summary-failure-base");var summary=store.summary(1,s.id(),s.activeBranchId(),"failed-summary-one","mock-text",Map.of());var r=claim(s);finish(r,"FAILED","");assertEquals(summary.id(),store.summary(1,s.id(),s.activeBranchId(),"failed-summary-two","mock-text",Map.of()).id());long version=base.branches(1,s.id()).get(0).version();var retried=store.retry(1,r.id(),"summary-explicit-retry",version,true).run();assertEquals("SUMMARY",retried.kind());assertEquals(retried.id(),jdbc.queryForObject("SELECT current_run_id FROM assistant_summaries",UUID.class));assertEquals(2,jdbc.queryForObject("SELECT count(*) FROM assistant_runs WHERE kind='SUMMARY'",Integer.class));}
