 @Test void citationsChoicesClassificationAndAtomicChoiceReplayPersist(){var s=session(1);store.admit(1,command(s,"choice-source","构图"));var r=claim(s);var citation=new Citation(UUID.randomUUID(),1,"PLATFORM_ARTWORK",UUID.randomUUID().toString(),"revision-1","public-v1",Map.of("title","待考"),"reference","52367a6622b19f08825e915fad80c542ad4f4c34dbcebad9f5007994b3e39208");var card=new ChoiceCard("direction","选择方向",List.of(new ChoiceOption("a","留白","讨论留白"),new ChoiceOption("b","设色","讨论设色")));store.savePreparation(1,r.id(),r.fence(),"worker-1",Map.of("messageIds",List.of(r.inputMessageId().toString())),List.of(citation),Map.of("artworks","FOUND","ragflow","TIMEOUT"));store.complete(1,r.id(),r.fence(),"worker-1","COMPLETED","answer [C1]",List.of(citation),Map.of("inputTokens",12),List.of(card));assertEquals("TIMEOUT",store.get(1,r.id()).retrieval().get("ragflow"));assertEquals(citation.id(),store.citations(1,r.id()).get(0).id());assertEquals(1,store.choices(1,r.id()).size());var command=command(s,"choice-click","ignored client text");var selected=store.choice(1,r.id(),"direction","a",command);assertEquals(selected.run().id(),store.choice(1,r.id(),"direction","a",command).run().id());assertEquals(selected.run().id(),store.replayChoice(1,r.id(),"direction","a",command).orElseThrow().run().id());fail(409,()->store.choice(1,r.id(),"direction","b",command));assertEquals("讨论留白",store.context(1,selected.run().id(),32).get(2).body());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM assistant_interaction_selections",Integer.class));assertEquals("构图规划",store.timeline(1,s.id()).get(0).classification());var label=store.classify(1,s.id(),r.inputMessageId(),"classify-message",1,"灵感构思");assertEquals("USER",label.get("source"));assertEquals(2,label.get("version"));base.deleteSession(1,s.id());fail(410,()->store.replayChoice(1,r.id(),"direction","a",command));fail(409,()->store.replayChoice(1,r.id(),"direction","b",command));}
