 @Test void standaloneRetrievalHasItsOwnIdentityAndDoesNotCreateAChat(){var s=session(1);var c=command(s,"retrieval-only-key","山水");var accepted=store.retrieval(1,c);assertEquals("RETRIEVAL",accepted.run().kind());assertEquals("_retrieval",accepted.run().modelId());assertEquals(accepted.run().id(),store.retrieval(1,c).run().id());var run=claim(s);store.markIntent(1,run.id(),run.fence(),"worker-1","RETRIEVAL");store.complete(1,run.id(),run.fence(),"worker-1","COMPLETED","",List.of(),Map.of(),List.of());assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM assistant_runs WHERE kind='CHAT'",Integer.class));assertEquals(0,jdbc.queryForObject("SELECT count(*) FROM assistant_messages WHERE role='ASSISTANT'",Integer.class));}
 @Test void automaticSummaryRequiresOptInIdleCompletedHeadAndNoBusyTurn(){var s=session(1);completed(s,"auto-first-chat");clock.value=clock.value.plusSeconds(31);assertTrue(store.automaticSummaryCandidates(1,Duration.ofSeconds(30),10).isEmpty());var current=base.session(1,s.id());base.updateSession(1,s.id(),current.version(),null,null,true);var candidates=store.automaticSummaryCandidates(1,Duration.ofSeconds(30),10);assertEquals(1,candidates.size());assertEquals("mock-text",candidates.get(0).modelId());store.admit(1,command(s,"auto-busy-chat","next"));assertTrue(store.automaticSummaryCandidates(1,Duration.ofSeconds(30),10).isEmpty());}
 @Test void pendingCapacityIsBoundedAcrossSessionsAndOwners(){
  var bounded=new AssistantExecutionStore(jdbc.getDataSource(),base,clock,Duration.ofHours(1),4,4,2,1,3,2);
  var a=session(1);var b=session(1);var c=session(1);var d=session(2);var e=session(2);
  bounded.admit(1,command(a,"pending-first","a"));bounded.admit(1,command(b,"pending-second","b"));fail(429,()->bounded.admit(1,command(c,"pending-owner-limit","c")));
  bounded.admit(2,new Admission(d.id(),d.activeBranchId(),0,"pending-third","d",List.of(),"mock-text",Map.of()));fail(429,()->bounded.admit(2,new Admission(e.id(),e.activeBranchId(),0,"pending-global-limit","e",List.of(),"mock-text",Map.of())));
  assertEquals(3,jdbc.queryForObject("SELECT count(*) FROM assistant_runs",Integer.class));assertEquals(3,jdbc.queryForObject("SELECT count(*) FROM assistant_messages",Integer.class));
 }
 @Test void retrievalIntentAlsoBecomesUncertainWithoutAutomaticReplay(){var s=session(1);store.retrieval(1,command(s,"uncertain-rag","reference"));var r=claim(s);store.markIntent(1,r.id(),r.fence(),"worker-1","RETRIEVAL");clock.value=clock.value.plusSeconds(11);store.recoverExpired(10);var finalRun=store.get(1,r.id());assertTrue(finalRun.executionUncertain());assertEquals("DISPATCH_RESULT_UNCERTAIN",finalRun.lastError());assertTrue(store.pendingSessions(10).isEmpty());}
 @Test void editedImageReplayUsesImmutableForkAfterHeadMovesAndDeletion(){
  var s=session(1);UUID image=UUID.randomUUID();base.reserveAttachment(1,s.id(),"edited-image-upload","a".repeat(64),image,image.toString(),"fixture.png","image/png",8,"b".repeat(64),1,1);base.readyAttachment(1,image,1,1);
  var first=store.admit(1,new Admission(s.id(),s.activeBranchId(),0,"edited-image-first","original",List.of(image),"mock-vision",Map.of())).run();var running=claim(s);finish(running,"COMPLETED","original answer");var branch=base.branches(1,s.id()).get(0);var revised=base.reviseMessage(1,s.id(),branch.id(),first.inputMessageId(),branch.version(),"edited-image-revise","revised image question");
  var persisted=new Admission(s.id(),revised.id(),revised.version(),"edited-image-run","revised image question",List.of(image),"mock-vision",Map.of());var browser=new Admission(s.id(),revised.id(),revised.version(),"edited-image-run","revised image question",List.of(),"mock-vision",Map.of());assertTrue(store.replayEditedInput(1,browser).isEmpty());var accepted=store.admitEdited(1,persisted).run();assertEquals(accepted.id(),store.replayEditedInput(1,browser).orElseThrow().run().id());var active=claim(s);finish(active,"COMPLETED","edited answer");assertEquals(accepted.id(),store.replayEditedInput(1,browser).orElseThrow().run().id());fail(404,()->store.ownedSessionForRequest(2,accepted.id()));base.deleteSession(1,s.id());jdbc.update("DELETE FROM assistant_message_attachments WHERE session_id=?",s.id());assertEquals(s.id(),store.ownedSessionForRequest(1,accepted.id()));fail(410,()->store.replayEditedInput(1,browser));fail(409,()->store.replayEditedInput(1,new Admission(s.id(),revised.id(),revised.version(),"edited-image-run","changed payload",List.of(),"mock-vision",Map.of())));
 }
 @Test void concurrentClaimersShareTheDatabaseGlobalExecutingLimit()throws Exception{
  var limited=new AssistantExecutionStore(jdbc.getDataSource(),base,clock,Duration.ofHours(1),4,4,1,1);var first=session(1);var second=session(2);limited.admit(1,command(first,"concurrent-slot-a","a"));limited.admit(2,new Admission(second.id(),second.activeBranchId(),0,"concurrent-slot-b","b",List.of(),"mock-text",Map.of()));var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);
  try{var a=pool.submit(()->{start.await();return limited.claim(1,first.id(),"concurrent-worker-a",Duration.ofSeconds(10));});var b=pool.submit(()->{start.await();return limited.claim(2,second.id(),"concurrent-worker-b",Duration.ofSeconds(10));});start.countDown();var left=a.get(5,TimeUnit.SECONDS);var right=b.get(5,TimeUnit.SECONDS);assertEquals(1,(left.isPresent()?1:0)+(right.isPresent()?1:0));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM assistant_runs WHERE status='EXECUTING'",Integer.class));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM assistant_runs WHERE status='QUEUED'",Integer.class));}finally{pool.shutdownNow();}
 }
 @Test void concurrentIdenticalAdmissionsPersistOneUserAndOneRun()throws Exception{
  var s=session(1);var command=command(s,"concurrent-identical-chat","question");var start=new CountDownLatch(1);var pool=Executors.newFixedThreadPool(2);
  try{var a=pool.submit(()->{start.await();return store.admit(1,command);});var b=pool.submit(()->{start.await();return store.admit(1,command);});start.countDown();var left=a.get(5,TimeUnit.SECONDS);var right=b.get(5,TimeUnit.SECONDS);assertEquals(left.run().id(),right.run().id());assertNotEquals(left.replay(),right.replay());assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM assistant_messages WHERE role='USER'",Integer.class));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM assistant_runs",Integer.class));assertEquals(1,jdbc.queryForObject("SELECT count(*) FROM assistant_requests WHERE operation='CHAT_EXECUTION'",Integer.class));}finally{pool.shutdownNow();}
 }
